#### Drawing the Game State
```c
void drawGame(SDL_Renderer* renderer,
             SDL_Texture* snakeHeadTexture,
             SDL_Texture* snakeBodyTexture,
             SDL_Texture* foodTexture,
             struct snakeParts[] ,
             int snakeLength,
             int foodX,
             int foodY) {
    for (int i = 0; i < snakeLength; i++) {
        int x = snakeParts[i].x * 20; // Calculate pixel position from grid coordinates
        int y = snakeParts[i].y * 20;

        if (i == 0) {
            drawTexture(renderer, snakeHeadTexture, x, y);
        } else {
            drawTexture(renderer, snakeBodyTexture, x, y);
        }
    }

    drawTexture(renderer, foodTexture, foodX * 20, foodY * 20);
}
```

### Helper Function for Drawing Textures at a Given Position
```c
void drawTexture(SDL_Renderer* renderer, SDL_Texture* texture, int x, int y) {
    SDL_Rect destRect = {x, y, texture->GetWidth(), texture->GetHeight()};
    SDL_RenderCopy(renderer, texture, NULL, &destRect);
}
```

### Cleaning Up Resources

```c
void unloadTextures(SDL_Texture** textures, int count) {
    for (int i = 0; i < count; i++) {
        SDL_DestroyTexture(textures[i]);
    }
}
